import json, re
from pathlib import Path
base=Path('/user/user1/autorlbench-runs/20261122020208-61145-174a/workspace/results/grpo_gsm8k')

def extract(solution_str, method="flexible"):
    if len(solution_str) > 300:
        solution_str = solution_str[-300:]
    if method == "strict":
        solutions = re.findall(r"#### (\-?[0-9\.\,]+)", solution_str)
        if not solutions:
            return None
        return solutions[-1].replace(",", "").replace("$", "")
    else:
        answer = re.findall(r"(\-?[0-9\.\,]+)", solution_str)
        if not answer:
            return None
        invalid_str = ["", "."]
        final_answer=None
        for final_answer in reversed(answer):
            if final_answer not in invalid_str:
                break
        return final_answer

# mismatches
rows=[]
with open(base/'rollouts/1.jsonl') as f:
    for line in f:
        rows.append(json.loads(line))
print('--- mismatches rollout 1 ---')
for r in rows:
    a=extract(r['output'])
    s=0 if a is None else (1.0 if a==str(r['gts']) else 0.0)
    if abs(s-r['score'])>1e-6:
        print('score', r['score'], 'recomputed', s, 'ans', a, 'gt', r['gts'])
        print('TAIL', repr(r['output'][-350:]))
        print('---')

# look at a few correct and incorrect outputs
print('\n===== SAMPLE CORRECT =====')
c=0
for r in rows:
    if r['score']==1 and c<2:
        print('GT', r['gts'], 'LEN', len(r['output']))
        print(r['output'][-500:])
        print('====')
        c+=1
print('\n===== SAMPLE INCORRECT =====')
c=0
for r in rows:
    if r['score']==0 and c<3:
        print('GT', r['gts'], 'LEN', len(r['output']), 'extracted', extract(r['output']))
        print(r['output'][-600:])
        print('====')
        c+=1

# token-ish: responses that look cut off (don't end with sentence)
print('\n===== ending patterns rollout 1 =====')
endings=Counter= __import__('collections').Counter()
for r in rows:
    t=r['output'].rstrip()
    if t.endswith('####') or re.search(r'####\s*$', t):
        endings['ends_hash_incomplete']+=1
    elif re.search(r'\d$', t):
        endings['ends_digit']+=1
    elif t.endswith('.') or t.endswith('!') or t.endswith('?'):
        endings['ends_punct']+=1
    elif t.endswith('```'):
        endings['ends_code']+=1
    else:
        endings['other']+=1
print(endings)

# Check if many responses end mid-word / mid-sentence and last number is intermediate
# Compare last number vs any number equal to gt
print('\n===== reward hacking style analysis =====')
for name in ['rollouts/1.jsonl','rollouts/50.jsonl','val_generations/0.jsonl','val_generations/50.jsonl']:
    rows=[]
    with open(base/name) as f:
        for line in f:
            rows.append(json.loads(line))
    n=len(rows)
    gt_anywhere=0
    gt_is_last=0
    gt_in_text_not_last=0
    early_stop_reward=0  # last number equals gt but response < 400 chars and no ####
    repeating=0
    very_short=0  # <100 chars
    for r in rows:
        out=r['output']
        gt=str(r['gts'])
        nums=re.findall(r'(\-?[0-9\.\,]+)', out)
        nums=[x for x in nums if x not in ('','.')]
        if gt in nums or gt in out:
            # exact token-ish
            if re.search(r'(?<![\d\.])'+re.escape(gt)+r'(?![\d\.])', out):
                gt_anywhere += 1
        last=nums[-1].replace(',','') if nums else None
        if last==gt:
            gt_is_last += 1
        if re.search(r'(?<![\d\.])'+re.escape(gt)+r'(?![\d\.])', out) and last!=gt:
            gt_in_text_not_last += 1
        if len(out)<100:
            very_short += 1
        # repetition: a sentence repeated
        if len(out)>200:
            # crude: unique line ratio
            lines=[ln.strip() for ln in out.splitlines() if ln.strip()]
            if len(lines)>=6 and len(set(lines))/len(lines)<0.6:
                repeating += 1
    print(name, f'n={n} gt_anywhere={gt_anywhere/n:.3f} last_eq_gt={gt_is_last/n:.3f} gt_present_but_not_last={gt_in_text_not_last/n:.3f} very_short={very_short} repeating_lines={repeating}')
